"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[3230],{97902:e=>{e.exports=JSON.parse('{"tag":{"label":"Data Management","permalink":"/science/tags/data-management","allTagsPath":"/science/tags","count":5,"items":[{"id":"2024/llm-generation","title":"Code Generation and Documentation Search using Large Language Model","description":"Author: Aldo Malaquias Cabrera, Summer 2024","permalink":"/science/2024/llm-generation"},{"id":"2024/finding-events","title":"Creating a System to Find Events in Real Time","description":"Across the United States and the world, the distributed network of Sage nodes captures over 2500 images per day. These nodes have the potential of capturing photos with important features such as smoke, wildlife, and emergencies. Each image contains unique characteristics which, until now, were hard to look for without manually searching through the Sage database. With both the images and users in mind, this project has two goals: harness the power of machine learning to describe photos as they are taken, and build a user-friendly system to allow others to find what they are looking for within our database.","permalink":"/science/2024/finding-events"},{"id":"2026/image-search-at-the-edge","title":"Image Search at the Edge","description":"Authors: Sajan Neupane (University of Utah) and Pratik Kharade (University of Utah \u2013 SCI Institute)","permalink":"/science/2026/image-search-at-the-edge"},{"id":"2026/ndp-scidx-mcp","title":"Sage-NDP-SciDx MCP","description":"Authors: Pratik Kharade (University of Utah \u2013 SCI Institute) and Sajan Neupane (University of Utah)","permalink":"/science/2026/ndp-scidx-mcp"},{"id":"2023/scalable-ci-in-aps","title":"Scalable AI@Edge Computing in X-ray Beamline Experiments","description":"Can Edge Computing Be Used in X-Ray Beamline Experiments to Process a High-Volume and Fast Data Stream and Help Scientists Make Real-Time Decisions for Experiments?","permalink":"/science/2023/scalable-ci-in-aps"}],"unlisted":false}}')}}]);